                new CalculoCupom(pedido.itens(), subtotalProdutos, frete));

        FormaPagamento pagamento = exigir(
                Codigos.procurar(FormaPagamento.class, requisicao.formaPagamento()),
                CodigoErro.FORMA_PAGAMENTO_INVALIDA);
